test('Batch 13 all twenty lessons pass real handlers with wrong/retry, independent locking, drafts and resume',()=>{
 const oldDoc=globalThis.document,oldStorage=globalThis.localStorage;
 try{for(const l of lessons.slice(155)){
  const h=harness();h.studio.openProgressLesson(l.id,0);assert(h.root.innerHTML.includes(l.topicId==='english-literature.unseen'?' / 15 in Unseen poetry':' / 20 in Reading and analytical writing'));assert(h.root.innerHTML.includes(l.topicId==='english-literature.unseen'?'PAPER 2':'SKILLS ACROSS PAPERS 1 AND 2'));h.studio.openSources();for(const r of l.contextReading)assert(h.modal().includes(r.label));
  for(let i=0;i<3;i++)h.$('#hContinue').click();for(const b of h.all('[data-lit-word]'))b.click();for(let i=1;i<3;i++)h.all('[data-hview]').find(b=>Number(b.dataset.hview)===i).click();h.all('[data-htask]').find(b=>Number(b.dataset.htask)!==l.tasks[0][2]).click();assert.equal(h.$('#hFeedback').textContent,l.tasks[0][4]);h.all('[data-htask]').find(b=>Number(b.dataset.htask)===l.tasks[0][2]).click();h.$('#hContinue').click();
  for(const q of l.practice){h.all('[data-hanswer]').find(b=>Number(b.dataset.hanswer)!==q.answer).click();h.all('[data-hanswer]').find(b=>Number(b.dataset.hanswer)===q.answer).click();assert.notEqual(h.studio.state().lessons[l.id].practice[q.id].first,q.answer);h.$('#hContinue').click();}
  for(const q of l.check){h.all('[data-hanswer]').find(b=>Number(b.dataset.hanswer)===q.answer).click();assert.equal(h.$('#hFeedback').textContent,'Answer recorded.');h.$('#hContinue').click();}assert(literatureGates(l,h.studio.state().lessons[l.id]).every(Boolean));h.$('#litDraft').value='My supported interpretation of '+l.id;h.$('#litDraft').oninput();h.$('#litSaveDraft').click();const r=harness(JSON.parse(h.storage.get(KEY)));r.studio.render();assert.equal(r.$('#litDraft').value,'My supported interpretation of '+l.id);assert.equal(r.studio.getProgress().completed,1);assert.equal(r.studio.getProgress().total,175);
 }}finally{cancelQuestionAdvance();globalThis.document=oldDoc;globalThis.localStorage=oldStorage;}
});
