  const r=harness(JSON.parse(h.storage.get(course.key)),course);r.studio.render();assert.equal(r.studio.state().lessonId,l.id);assert.equal(r.studio.getProgress().total,175);assert.equal(r.studio.getProgress().completed,1);assert(!r.storage.has(KEY));
